from _dsl import *
ORDER = 23
GRAPH = "edges = {'A': [('B', 3), ('C', 8)], 'B': [('C', 2), ('D', 9)], 'C': [('D', 4)], 'D': []}\n"
COUNT = GRAPH + "ways = {v: 0 for v in edges}\nways['A'] = 1\nfor v in ['A', 'B', 'C', 'D']:\n    for to, weight in edges[v]:\n        ways[to] += ways[v]\nprint(ways['D'])"
SHORTEST = GRAPH + "dist = {v: float('inf') for v in edges}\ndist['A'] = 0\nfor v in ['A', 'B', 'C', 'D']:\n    for to, weight in edges[v]:\n        dist[to] = min(dist[to], dist[v]+weight)\nprint(dist['D'])"
COND = p('Ориентированный граф: A→B (3), A→C (8), B→C (2), B→D (9), C→D (4). В скобках — длины рёбер.')
MODULE = module('m31', 'Графы: пути и расстояния', '↗', 'Архивная практика: пути в графах и расстояния. Не отдельный номер КИМ-2027.', [
    level('Динамика по графу', 'Различать количество маршрутов и их стоимость.', [
        txt('Сначала порядок', p('В DAG нет направленных циклов. Обрабатываем вершины после всех их предшественников. Для примера подходит A,B,C,D. Алфавитный порядок в произвольном графе не гарантирован.')),
        code('Количество путей', COUNT, cond=COND, note='Для старта задаём 1 путь. Результат передаём всем следующими рёбрами.'),
        code('Кратчайший путь', SHORTEST, cond=COND, note='Недостижимую вершину обозначаем бесконечностью. Здесь рёбра не меняются, меняется операция обновления.'),
    ], [
        task('paths', 'После добавления ребра', COND+p('Добавили ребро A→D. Сколько путей из A в D теперь?'), COUNT.replace("'A': [('B', 3), ('C', 8)]", "'A': [('B', 3), ('C', 8), ('D', 20)]"), hint='Прямое ребро добавляет отдельный путь.'),
        task('shortest', 'Запрещённая дорога', COND+p('Ребро B→C закрыто. Найди длину кратчайшего пути A→D.'), SHORTEST.replace("'B': [('C', 2), ('D', 9)]", "'B': [('D', 9)]"), hint='Сравни A-B-D и A-C-D.'),
        task('longest', 'Самый длинный путь', COND+p('Найди длину самого длинного пути A→D.'), SHORTEST.replace("float('inf')", "float('-inf')").replace('min(dist[to]', 'max(dist[to]'), hint='В DAG можно использовать максимум, а недостижимость обозначить −∞.'),
    ], need=2),
])
